        std::array<double, 9> left{}, right{};
        std::array<double, 10> stereo{};
        if (getLeftCamera(left.data()) || getRightCamera(right.data()) || getStereoCamera(stereo.data()))
            return false;
        const auto file = trackerPath.parent_path() / L"boe_mcu_mat.ini";
        return ReadIniArray(file, L"E1", left.data(), left.size()) &&
               ReadIniArray(file, L"E2", right.data(), right.size()) &&
               ReadIniArray(file, L"E3", stereo.data(), stereo.size());
